mapper.select:
select sum(check_difference_count) as check_difference_count, material_id, dept_id, dept_name from ( ( select sum(t5.actual_count - t5.rfid_head_count) as check_difference_count, t5.material_id, t2.dept_id, t2.dept_name from t_check_result t1 inner join t_task_detail t2 on t1.task_detail_id = t2.id inner join t_check_history t5 on t1.task_detail_id = t5.task_detail_id and t5.del_flag = '0' where t1.del_flag = '0' and t2.dept_id = #{deptId} and t5.material_id in
#{item}
and t5.material_code like concat('%',#{materialCode},'%') group by t2.dept_id,t2.dept_name,t5.material_id ) union all ( select sum(t6.actual_count - t6.predict_count) as check_difference_count, t6.material_id, t2.dept_id, t2.dept_name from t_check_result t1 inner join t_task_detail t2 on t1.task_detail_id = t2.id inner join t_check_area_history t6 on t1.task_detail_id = t6.task_detail_id and t6.del_flag = '0' and t6.status = '4' where t1.del_flag = '0' and t2.dept_id = #{deptId} and t6.material_id in
#{item}
and t6.batch_number like concat('%', #{materialCode}, '%') group by t2.dept_id,t2.dept_name,t6.material_id ) ) t group by dept_id,dept_name,material_id
